ProjectRole = Literal["owner", "editor", "reader"]
ScientificAction = Literal["read", "write", "manage"]
# B01 and workload bindings use UUID scope identities. This new workspace
# contract is unpublished; legacy scientific Scope keeps its existing meaning.
ProjectId = Annotated[
    str,
    StringConstraints(
        pattern=r"^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$"
    ),
]


