class ProjectReceipt(Contract):
    schema_version: Literal["forge.project-receipt.v1"] = "forge.project-receipt.v1"
    organization_id: Identifier
    project_id: ProjectId
    operation_id: Identifier
    request_digest_sha256: Digest
    state_digest_sha256: Digest
    recorded_at: AwareDatetime
    principal: ProjectPrincipal
    state: ProjectState

    @model_validator(mode="after")
    def state_identity(self):
        if (
            self.organization_id != self.state.organization_id
            or self.project_id != self.state.project_id
            or self.principal.organization_id != self.organization_id
            or self.state_digest_sha256 != contract_digest(self.state)
        ):
            raise ValueError("project receipt differs from retained state")
        return self


